import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Proofs as First-Class Values","description":"","frontmatter":{"title":"Proofs as First-Class Values","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed\\n\\nBuilds on [ADR-0042 — Transformations as First-Class Values](./0042-transformations-as-first-class-values.md)."},"headers":[],"relativePath":"handl/project/adrs/0043-proofs-as-first-class-values.md","filePath":"vendored/handl/project/adrs/0043-proofs-as-first-class-values.md"}`),a={name:`handl/project/adrs/0043-proofs-as-first-class-values.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0043-proofs-as-first-class-values" tabindex="-1">ADR-0043: Proofs as First-Class Values <a class="header-anchor" href="#adr-0043-proofs-as-first-class-values" aria-label="Permalink to “ADR-0043: Proofs as First-Class Values”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Make proofs first-class handl values. A proof is a value that attests to a property of a transformation. The runtime verifies proofs before applying the transformations they certify.</p><h3 id="_1-proofs-are-handl-values" tabindex="-1">1. Proofs are handl values <a class="header-anchor" href="#_1-proofs-are-handl-values" aria-label="Permalink to “1. Proofs are handl values”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a proof is a value: Transformation -&gt; Proof</span></span>
<span class="line"><span>correct: type.any = (t: type.any) -&gt; prove-preserves-semantics(t);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># prove that a specific compiler is semantics-preserving</span></span>
<span class="line"><span>wasm-compiler: type.any = to-wasm(handl);</span></span>
<span class="line"><span>wasm-proof:    type.any = correct(wasm-compiler);    # a proof value</span></span></code></pre></div><p>The proof is constructed (offline, by a solver, or by a human) and then carried as a value alongside the transformation it certifies.</p><h3 id="_2-verification-is-a-runtime-check" tabindex="-1">2. Verification is a runtime check <a class="header-anchor" href="#_2-verification-is-a-runtime-check" aria-label="Permalink to “2. Verification is a runtime check”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># compiler correctness becomes a runtime check, not a paper theorem</span></span>
<span class="line"><span>safe-compile: type.any = (l: type.any) -&gt; {</span></span>
<span class="line"><span>  t: type.any = to-wasm(l);</span></span>
<span class="line"><span>  p: type.any = correct(t);</span></span>
<span class="line"><span>  if verify(p) then apply(t, l) else reject</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>The runtime checks the proof value before applying the transformation. No trust in the toolchain; only trust in the verifier (which is small and fixed, the way a typechecker is small and fixed).</p><h3 id="_3-proofs-compose-with-transformations" tabindex="-1">3. Proofs compose with transformations <a class="header-anchor" href="#_3-proofs-compose-with-transformations" aria-label="Permalink to “3. Proofs compose with transformations”">​</a></h3><p>If <code>p1</code> proves <code>t1</code> correct and <code>p2</code> proves <code>t2</code> correct, then <code>compose-proofs(p1, p2)</code> proves <code>compose(t1, t2)</code> correct — provided the notion of correctness is compositional (semantics preservation is).</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># compose transformations and their proofs together</span></span>
<span class="line"><span>pipeline: type.any = compose(optimize, strip-io);</span></span>
<span class="line"><span>proof:   type.any = compose-proofs(proof-optimize, proof-strip-io);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the composed pipeline is certified by the composed proof</span></span>
<span class="line"><span>if verify(proof) then apply(pipeline, handl) else reject;</span></span></code></pre></div><p>Proof composition mirrors transformation composition. A compiler pipeline ships with a composed proof, and the runtime verifies the composed proof once, not each pass individually.</p><h3 id="_4-certified-compilation" tabindex="-1">4. Certified compilation <a class="header-anchor" href="#_4-certified-compilation" aria-label="Permalink to “4. Certified compilation”">​</a></h3><p>A compiler ships as a pair: <code>(transformation, proof)</code>. The runtime verifies the proof before running the compiler. This is proof-carrying code at the language level.</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a certified compiler is a value: (Transformation, Proof)</span></span>
<span class="line"><span>certified-wasm: type.any = {</span></span>
<span class="line"><span>  transform: to-wasm,</span></span>
<span class="line"><span>  proof:     correct(to-wasm),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the runtime verifies before applying</span></span>
<span class="line"><span>run-certified: type.any = (cert: type.any, l: type.any) -&gt; {</span></span>
<span class="line"><span>  if verify(cert.proof) then apply(cert.transform, l) else reject</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="_5-verified-interop" tabindex="-1">5. Verified interop <a class="header-anchor" href="#_5-verified-interop" aria-label="Permalink to “5. Verified interop”">​</a></h3><p>A translator <code>A -&gt; B</code> ships with a proof that it faithfully translates. Polyglot interop stops being &quot;trust the bridge&quot; and becomes &quot;verify the translator.&quot;</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>json-to-handl-cert: type.any = {</span></span>
<span class="line"><span>  transform: json-to-handl,</span></span>
<span class="line"><span>  proof:     prove-faithful(json-to-handl),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># verified translation at runtime</span></span>
<span class="line"><span>if verify(json-to-handl-cert.proof) then</span></span>
<span class="line"><span>  eval(handl, translate(json-to-handl-cert.transform, json-src))</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  reject;</span></span></code></pre></div><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0041 made <code>Language</code> a first-class value. ADR-0042 made transformations <code>Language -&gt; Language</code> first-class values. The next operator up is the one that operates on transformations: <strong>the claim that a transformation is correct</strong> — that <code>compile(L, &quot;wasm&quot;)</code> preserves L&#39;s semantics, that <code>optimize</code> is semantics-preserving, that a translator <code>A -&gt; B</code> faithfully translates.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Compiler correctness becomes a runtime check.</strong> A compiler ships</li><li><strong>Proofs compose with transformations.</strong> A pipeline&#39;s proof is the</li><li><strong>Certified compilation.</strong> A compiler is a <code>(transformation, proof)</code></li><li><strong>Verified interop.</strong> A translator ships with a faithfulness proof.</li><li><strong>The tower is uniform.</strong> Proofs are values in a language,</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0043-proofs-as-first-class-values.html"><code>design/0043-proofs-as-first-class-values.md</code></a>.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};